/* Twitch Theme - Official Twitch brand colors */

/* Light mode */
[data-theme="twitch-light"] {
  --background: rgb(246, 244, 245);
  --foreground: rgb(9, 9, 11);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(9, 9, 11);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(9, 9, 11);
  --primary: rgb(120, 47, 251);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(235, 234, 245);
  --secondary-foreground: rgb(21, 21, 26);
  --muted: rgb(241, 237, 238);
  --muted-foreground: rgb(98, 99, 105);
  --accent: rgb(103, 21, 225);
  --accent-foreground: rgb(255, 255, 255);
  --destructive: rgb(212, 9, 36);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(225, 221, 222);
  --input: rgb(232, 227, 228);
  --ring: rgb(120, 47, 251);
  --chart-1: rgb(120, 47, 251);
  --chart-2: rgb(103, 21, 225);
  --chart-3: rgb(0, 163, 170);
  --chart-4: rgb(76, 184, 106);
  --chart-5: rgb(200, 65, 165);
  --radius: 0.5rem;
  --sidebar: rgb(250, 248, 248);
  --sidebar-foreground: rgb(9, 9, 11);
  --sidebar-primary: rgb(120, 47, 251);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(235, 234, 245);
  --sidebar-accent-foreground: rgb(21, 21, 26);
  --sidebar-border: rgb(225, 221, 222);
  --sidebar-ring: rgb(120, 47, 251);
  --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", monospace;
  --shadow-color: rgb(20, 0, 51);
  --shadow-opacity: 0.08;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(263 100% 10% / 0.04);
  --shadow-xs: 0 1px 3px 0px hsl(263 100% 10% / 0.06);
  --shadow-sm:
    0 2px 4px 0px hsl(263 100% 10% / 0.08),
    0 1px 2px -1px hsl(263 100% 10% / 0.08);
  --shadow:
    0 2px 4px 0px hsl(263 100% 10% / 0.08),
    0 1px 2px -1px hsl(263 100% 10% / 0.08);
  --shadow-md:
    0 4px 6px 0px hsl(263 100% 10% / 0.1),
    0 2px 4px -1px hsl(263 100% 10% / 0.1);
  --shadow-lg:
    0 8px 10px 0px hsl(263 100% 10% / 0.1),
    0 4px 6px -1px hsl(263 100% 10% / 0.1);
  --shadow-xl:
    0 16px 20px 0px hsl(263 100% 10% / 0.12),
    0 8px 10px -1px hsl(263 100% 10% / 0.12);
  --shadow-2xl: 0 24px 48px 0px hsl(263 100% 10% / 0.2);
  --tracking-normal: -0.01em;
}

/* Dark mode - #0E0E10 is Twitch's signature dark background */
[data-theme="twitch-dark"] {
  --background: rgb(9, 9, 11);
  --foreground: rgb(240, 238, 238);
  --card: rgb(17, 17, 21);
  --card-foreground: rgb(240, 238, 238);
  --popover: rgb(22, 22, 26);
  --popover-foreground: rgb(240, 238, 238);
  --primary: rgb(120, 47, 251);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(26, 26, 30);
  --secondary-foreground: rgb(224, 221, 222);
  --muted: rgb(22, 22, 25);
  --muted-foreground: rgb(142, 142, 149);
  --accent: rgb(164, 145, 255);
  --accent-foreground: rgb(9, 9, 11);
  --destructive: rgb(222, 59, 61);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(40, 40, 46);
  --input: rgb(26, 26, 30);
  --ring: rgb(120, 47, 251);
  --chart-1: rgb(120, 47, 251);
  --chart-2: rgb(164, 145, 255);
  --chart-3: rgb(0, 180, 187);
  --chart-4: rgb(101, 198, 125);
  --chart-5: rgb(211, 91, 177);
  --radius: 0.5rem;
  --sidebar: rgb(6, 6, 7);
  --sidebar-foreground: rgb(240, 238, 238);
  --sidebar-primary: rgb(120, 47, 251);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(26, 26, 30);
  --sidebar-accent-foreground: rgb(224, 221, 222);
  --sidebar-border: rgb(40, 40, 46);
  --sidebar-ring: rgb(120, 47, 251);
  --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.4;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(0 0% 0% / 0.2);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.3);
  --shadow-sm:
    0 2px 4px 0px hsl(0 0% 0% / 0.4), 0 1px 2px -1px hsl(0 0% 0% / 0.4);
  --shadow: 0 2px 4px 0px hsl(0 0% 0% / 0.4), 0 1px 2px -1px hsl(0 0% 0% / 0.4);
  --shadow-md:
    0 4px 6px 0px hsl(0 0% 0% / 0.4), 0 2px 4px -1px hsl(0 0% 0% / 0.4);
  --shadow-lg:
    0 8px 10px 0px hsl(0 0% 0% / 0.4), 0 4px 6px -1px hsl(0 0% 0% / 0.4);
  --shadow-xl:
    0 16px 20px 0px hsl(0 0% 0% / 0.4), 0 8px 10px -1px hsl(0 0% 0% / 0.4);
  --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.5);
}
